// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _test(address caller, address depositor) internal {
        bool succeeded;
        address originalDepositor;
        try c.depositorAccount() returns (address __r) { originalDepositor = __r; } catch { return; }
        vm.assume(caller != depositor);
        bool reverted = false;
        try c.setL1BlockValues(0, 0, 0, bytes32(0), 0, bytes32(0), 0, 0) {
            succeeded = true;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (address(this) != c.depositorAccount()));
    }

    function testFuzz_test(address caller, address depositor) public {
        _test(caller, depositor);
    }

    receive() external payable {}
}
